<?php

namespace Tests\Feature;

use App\Domain\Catalog\Models\Track;
use App\Domain\Media\MediaFailure;
use App\Domain\Media\MediaProcessor;
use App\Domain\Media\QueueMediaProcessing;
use App\Domain\Media\StagingSellerTag;
use App\Models\User;
use Illuminate\Foundation\Testing\RefreshDatabase;
use Illuminate\Support\Facades\Artisan;
use Illuminate\Support\Facades\Storage;
use Tests\Support\MediaFixtures;
use Tests\TestCase;

/**
 * The synthetic STAGING seller tag: generated by ffmpeg on the host, valid for the real media pipeline, marked three ways,
 * and refused wherever the environment is not local, testing or staging.
 */
class StagingSellerTagTest extends TestCase
{
    use RefreshDatabase;

    private User $actor;

    private Track $track;

    protected function setUp(): void
    {
        parent::setUp();
        $this->fakePrivateMediaStorage();
        MediaFixtures::configure();
        // The host state before the seller-tag step: the template's placeholder, no tag installed under it.
        config(['media.tag_path' => 'branding/<approved-tag-file>.wav', 'media.tag_sha256' => '<64 lowercase hex from sha256sum>', 'media.tag_interval_seconds' => 30]);
        $this->actor = User::factory()->create();
        $this->actor->forceFill(['is_admin' => true])->save();
        $this->track = Track::create(['title' => 'Synthetic fixture', 'slug' => 'synthetic-fixture']);
    }

    private function run_(array $options = []): array
    {
        $exit = Artisan::call('vasey:staging-seller-tag', $options);

        return [$exit, Artisan::output()];
    }

    private function installedPath(): string
    {
        return Storage::disk('local')->path(StagingSellerTag::PATH);
    }

    private function generate(): string
    {
        [$exit, $output] = $this->run_();
        $this->assertSame(0, $exit, $output);

        return (string) hash_file('sha256', $this->installedPath());
    }

    private function failureCode(): string
    {
        $run = app(QueueMediaProcessing::class)->handle(MediaFixtures::source($this->track), $this->actor);
        try {
            app(MediaProcessor::class)->handle($run->id);
        } catch (MediaFailure $failure) {
            $this->assertSame(0, $run->refresh()->outputs()->count());
            $this->assertSame($failure->failureCode, $run->failure_code);

            return $failure->failureCode;
        }

        return 'completed';
    }

    public function test_it_installs_a_marked_owner_only_wav_and_prints_the_two_environment_lines(): void
    {
        [$exit, $output] = $this->run_();
        $this->assertSame(0, $exit, $output);
        $path = $this->installedPath();
        $this->assertFileExists($path);
        $this->assertSame('0600', substr(sprintf('%o', fileperms($path)), -4));
        $this->assertStringContainsString('STAGING', basename($path));
        $bytes = file_get_contents($path);
        $this->assertSame('RIFF', substr($bytes, 0, 4));
        $this->assertStringContainsString(StagingSellerTag::MARKER, $bytes);
        $this->assertStringContainsString(StagingSellerTag::TITLE, $bytes);
        $this->assertLessThan(200000, strlen($bytes));
        $this->assertStringContainsString('STAGING ONLY', $output);
        $this->assertStringContainsString('MEDIA_TAG_PATH='.StagingSellerTag::PATH, $output);
        $this->assertStringContainsString('MEDIA_TAG_SHA256='.hash('sha256', $bytes), $output);
        $this->assertStringContainsString('does not select this tag yet', $output);
        // Nothing but the tag stays behind: no temporary file beside it and no scratch workspace.
        $this->assertSame([basename($path)], array_values(array_diff(scandir(dirname($path)), ['.', '..'])));
        $this->assertSame([], array_values(array_diff(scandir(Storage::disk('local')->path('processing')), ['.', '..'])));
    }

    public function test_generation_is_repeatable_and_a_second_run_changes_nothing(): void
    {
        $first = $this->generate();
        $modified = filemtime($this->installedPath());
        config(['media.tag_path' => StagingSellerTag::PATH, 'media.tag_sha256' => $first]);
        [$exit, $output] = $this->run_();
        $this->assertSame(0, $exit, $output);
        $this->assertStringContainsString('Already installed and unchanged', $output);
        $this->assertStringContainsString('already selects this tag', $output);
        $this->assertSame($first, hash_file('sha256', $this->installedPath()));
        $this->assertSame($modified, filemtime($this->installedPath()));
        // A fresh generation elsewhere yields the same bytes on this ffmpeg build.
        unlink($this->installedPath());
        $this->assertSame($first, $this->generate());
    }

    public function test_check_installs_nothing(): void
    {
        [$exit, $output] = $this->run_(['--check' => true]);
        $this->assertSame(0, $exit, $output);
        $this->assertStringContainsString('nothing was installed', $output);
        $this->assertFileDoesNotExist($this->installedPath());
    }

    public function test_the_real_pipeline_accepts_the_generated_tag_where_it_is_admitted(): void
    {
        $sha256 = $this->generate();
        config(['media.tag_path' => StagingSellerTag::PATH, 'media.tag_sha256' => $sha256]);
        $run = app(QueueMediaProcessing::class)->handle(MediaFixtures::source($this->track), $this->actor);
        $run = app(MediaProcessor::class)->handle($run->id);
        $this->assertSame('completed', $run->status);
        $preview = $run->outputs()->where('role', 'preview_tagged')->firstOrFail();
        $this->assertSame($sha256, $preview->technical_metadata['tag_sha256']);
    }

    public function test_it_never_replaces_an_installed_seller_tag_or_a_different_file_at_its_own_path(): void
    {
        config(['media.tag_path' => 'approved-tags/test-only.wav']);
        [$exit, $output] = $this->run_();
        $this->assertSame(1, $exit);
        $this->assertStringContainsString('never replaces or overrides a seller tag', $output);
        $this->assertFileDoesNotExist($this->installedPath());

        config(['media.tag_path' => null]);
        Storage::disk('local')->put(StagingSellerTag::PATH, 'another file');
        [$exit, $output] = $this->run_();
        $this->assertSame(1, $exit);
        $this->assertStringContainsString('A different file is already at', $output);
        $this->assertSame('another file', file_get_contents($this->installedPath()));
    }

    public function test_production_and_an_ambiguous_environment_refuse_generation(): void
    {
        foreach ([['production', 'production'], ['production', 'staging'], ['staging', 'production'], ['staging-eu', 'staging-eu']] as [$configured, $running]) {
            config(['app.env' => $configured]);
            $this->app->instance('env', $running);
            [$exit, $output] = $this->run_();
            $this->assertSame(1, $exit, $configured.'/'.$running);
            $this->assertStringContainsString('Refused: The synthetic staging seller tag is generated only', $output);
            $this->assertFileDoesNotExist($this->installedPath());
            $this->assertFalse(StagingSellerTag::admitted());
        }
        foreach (['local', 'testing', 'staging'] as $environment) {
            config(['app.env' => $environment]);
            $this->app->instance('env', $environment);
            $this->assertTrue(StagingSellerTag::admitted(), $environment);
            $this->assertFalse(StagingSellerTag::refused(StagingSellerTag::PATH, null));
        }
    }

    public function test_the_media_pipeline_refuses_the_staging_tag_by_content_and_by_path_outside_admitted_environments(): void
    {
        $sha256 = $this->generate();
        // Renamed to look approved: the marker inside the file still refuses it.
        Storage::disk('local')->put('approved-tags/renamed.wav', file_get_contents($this->installedPath()));
        config(['media.tag_path' => 'approved-tags/renamed.wav', 'media.tag_sha256' => $sha256]);
        $this->assertSame('completed', $this->failureCode());
        config(['app.env' => 'production']);
        $this->assertSame('staging_tag_refused', $this->failureCode());

        // An unmarked file under a staging name is refused by its path.
        $plain = MediaFixtures::wav(0.2, 1800);
        Storage::disk('local')->put('branding/Staging-copy.wav', $plain);
        config(['media.tag_path' => 'branding/Staging-copy.wav', 'media.tag_sha256' => hash('sha256', $plain), 'media.tag_interval_seconds' => 1]);
        $this->assertSame('staging_tag_refused', $this->failureCode());

        // The approved tag is untouched by the guard in the same environment.
        Storage::disk('local')->put('approved-tags/test-only.wav', $plain);
        config(['media.tag_path' => 'approved-tags/test-only.wav']);
        $this->assertSame('completed', $this->failureCode());
    }

    public function test_the_marker_is_found_across_read_boundaries_and_an_unreadable_file_reads_as_marked(): void
    {
        $directory = Storage::disk('local')->path('marker-probe');
        mkdir($directory, 0700, true);
        foreach ([0, 65536 - 5, 65536, 3 * 65536 - 1] as $padding) {
            file_put_contents($directory.'/marked', str_repeat('x', $padding).StagingSellerTag::MARKER.'tail');
            $this->assertTrue(StagingSellerTag::fileCarriesMarker($directory.'/marked'), (string) $padding);
        }
        file_put_contents($directory.'/plain', str_repeat(substr(StagingSellerTag::MARKER, 0, -1), 9000));
        $this->assertFalse(StagingSellerTag::fileCarriesMarker($directory.'/plain'));
        $this->assertTrue(StagingSellerTag::fileCarriesMarker($directory.'/absent'));
        foreach (['branding/STAGING-synthetic-seller-tag.wav', 'x/staging.wav', 'Synthetic/tag.wav'] as $path) {
            $this->assertTrue(StagingSellerTag::pathCarriesMarker($path));
        }
        foreach (['branding/approved-seller-tag.wav', null, 7] as $path) {
            $this->assertFalse(StagingSellerTag::pathCarriesMarker($path));
        }
    }
}
